import { Controller, HttpCode, Put, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: dependentInfoEnc는 클라이언트/공통 모듈에서 이미 암호화된 문자열로 오며 그대로 저장한다.
// 가정: 본인 자료가 아니면 존재를 숨기기 위해 404로 응답한다.

const INVALID = 'YEAR_END_DATA_INVALID';

function provided(v: unknown): boolean {
  return v !== undefined && v !== null && v !== '';
}

@Controller('api/v1')
export class FnSfr03207Controller {
  @Put('/year-end-data/:yearEndDataId')
  async updateYearEndData2(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const data = checks.inputOf(req.body);
    const idText = req.params['yearEndDataId'];
    if (!/^\d+$/.test(idText)) {
      throw new ApiError(422, INVALID, '연말정산 자료 ID 형식이 올바르지 않습니다.');
    }

    const hasDeduction = provided(data['deductionAmount']);
    const hasDependent = provided(data['dependentInfoEnc']);
    const hasAttachment = provided(data['attachmentId']);
    if (!hasDeduction && !hasDependent && !hasAttachment) {
      throw new ApiError(422, INVALID, '수정할 값을 입력하세요.');
    }

    let deduction: string | null = null;
    if (hasDeduction) {
      const raw = data['deductionAmount'];
      const okNumber = typeof raw === 'number' && Number.isFinite(raw) && raw >= 0;
      const okText = typeof raw === 'string' && /^\d+(\.\d+)?$/.test(raw.trim());
      if (!okNumber && !okText) {
        throw new ApiError(422, INVALID, '공제 금액은 0 이상의 숫자여야 합니다.');
      }
      deduction = String(raw).trim();
    }

    let dependent: string | null = null;
    if (hasDependent) {
      if (typeof data['dependentInfoEnc'] !== 'string') {
        throw new ApiError(422, INVALID, '부양가족 정보 형식이 올바르지 않습니다.');
      }
      dependent = data['dependentInfoEnc'] as string;
    }

    let attachment: string | null = null;
    if (hasAttachment) {
      const raw = data['attachmentId'];
      const okInt = typeof raw === 'number' && Number.isInteger(raw) && raw > 0;
      const okText = typeof raw === 'string' && /^\d+$/.test(raw.trim());
      if (!okInt && !okText) {
        throw new ApiError(422, INVALID, '증빙 첨부파일 형식이 올바르지 않습니다.');
      }
      attachment = String(raw).trim();
    }

    return transaction(async (db) => {
      const rows = await db.query(
        'SELECT year_end_data_id AS "yearEndDataId", closed_yn AS "closedYn" FROM year_end_data WHERE year_end_data_id = CAST(:id AS bigint) AND employee_id = CAST(:userId AS bigint)',
        { id: idText, userId: user.id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'YEAR_END_DATA_NOT_FOUND', '연말정산 자료를 찾을 수 없습니다.');
      }
      if (rows[0]['closedYn'] === true) {
        throw new ApiError(409, 'YEAR_END_DATA_CLOSED', '마감된 자료는 수정할 수 없습니다.');
      }

      if (attachment !== null) {
        const found = await db.query(
          'SELECT attachment_id FROM attachment WHERE attachment_id = CAST(:attachmentId AS bigint)',
          { attachmentId: attachment },
        );
        if (found.length === 0) {
          throw new ApiError(422, INVALID, '증빙 첨부파일을 찾을 수 없습니다.');
        }
      }

      const updated = await db.query(
        'UPDATE year_end_data SET '
          + 'deduction_amount = CASE WHEN :hasDeduction THEN CAST(:deduction AS numeric) ELSE deduction_amount END, '
          + 'dependent_info_enc = CASE WHEN :hasDependent THEN :dependent ELSE dependent_info_enc END, '
          + 'attachment_id = CASE WHEN :hasAttachment THEN CAST(:attachmentId AS bigint) ELSE attachment_id END, '
          + 'updated_at = now() '
          + 'WHERE year_end_data_id = CAST(:id AS bigint) AND closed_yn = false '
          + 'RETURNING year_end_data_id AS "yearEndDataId", closed_yn AS "closedYn"',
        {
          id: idText,
          hasDeduction,
          deduction,
          hasDependent,
          dependent,
          hasAttachment,
          attachmentId: attachment,
        },
      );
      if (updated.length === 0) {
        throw new ApiError(409, 'YEAR_END_DATA_CLOSED', '마감된 자료는 수정할 수 없습니다.');
      }
      return updated[0];
    });
  }
}

