import { useState } from 'react';
import {
  Badge,
  Band,
  DataTable,
  DateText,
  Drawer,
  Field,
  Filters,
  Form,
  LookupSelect,
  Num,
  NumberInput,
  Pager,
  RefName,
  Tiles,
  call,
  useData,
} from '../kit';
import type { Page, PageProps, Row } from '../kit';

export default function FnSfr03207Page({ role, notify }: PageProps) {
  const [year, setYear] = useState<unknown>('');
  const [page, setPage] = useState(0);
  const [editing, setEditing] = useState<Row | null>(null);
  const [creating, setCreating] = useState(false);

  const list = useData<Page>(
    () => call<Page>('GET', '/year-end-data', role, undefined, { settlementYear: year, page, size: 20 }),
    [year, page],
  );
  const rows = list.data?.items ?? [];
  const closedCount = rows.filter((r) => r.closedYn === true).length;

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>자료 건수</h2>
        <Tiles items={[['전체', <Num value={list.data?.total ?? 0} />]]} />
      </section>
      <section className="box span-4">
        <h2>마감 자료</h2>
        <Tiles items={[['현재 쪽', <Num value={closedCount} />]]} />
      </section>
      <section className="box span-4">
        <h2>수정 가능</h2>
        <Tiles items={[['현재 쪽', <Num value={rows.length - closedCount} />]]} />
      </section>
      <section className="box span-12">
        <h2>연말정산 자료</h2>
        <Filters
          onSearch={() => {
            setPage(0);
            list.reload();
          }}
          onReset={() => {
            setYear('');
            setPage(0);
          }}
        >
          <Field label="귀속 연도">
            <NumberInput value={year} onChange={setYear} />
          </Field>
        </Filters>
        <Band total={list.data?.total}>
          <button type="button" onClick={() => setCreating(true)}>자료 입력</button>
        </Band>
        <DataTable
          rows={rows}
          empty="연말정산 자료가 없습니다."
          columns={[
            { key: 'settlementYear', label: '귀속 연도' },
            { key: 'employeeId', label: '임직원', render: (r) => <RefName table="employee" role={role} value={r.employeeId} /> },
            { key: 'yearEndItemId', label: '연말정산 항목', render: (r) => <RefName table="year_end_item" role={role} value={r.yearEndItemId} /> },
            { key: 'deductionAmount', label: '공제 금액', render: (r) => <Num value={r.deductionAmount} /> },
            { key: 'closedYn', label: '마감 여부', render: (r) => <Badge value={r.closedYn === true ? '마감' : '진행'} /> },
            { key: 'determinedTax', label: '결정세액', render: (r) => <Num value={r.determinedTax} /> },
            { key: 'prepaidTax', label: '기납부세액', render: (r) => <Num value={r.prepaidTax} /> },
            { key: 'settlementTax', label: '차감징수(환급)세액', render: (r) => <Num value={r.settlementTax} /> },
            {
              key: 'action',
              label: '처리',
              render: (r) => (r.closedYn === true ? null : (
                <button type="button" onClick={() => setEditing(r)}>수정</button>
              )),
            },
          ]}
        />
        <Pager page={page} size={list.data?.size ?? 20} total={list.data?.total ?? 0} onPage={setPage} />
      </section>
      {editing && (
        <Drawer title="연말정산 자료 수정" onClose={() => setEditing(null)}>
          <EditForm
            role={role}
            row={editing}
            onDone={() => {
              notify('연말정산 자료를 수정했습니다.');
              setEditing(null);
              list.reload();
            }}
          />
        </Drawer>
      )}
      {creating && (
        <Drawer title="연말정산 자료 입력" onClose={() => setCreating(false)}>
          <CreateForm
            role={role}
            onDone={() => {
              notify('연말정산 자료를 입력했습니다.');
              setCreating(false);
              list.reload();
            }}
          />
        </Drawer>
      )}
    </div>
  );
}

import { TextInput } from '../kit';

function EditForm({ role, row, onDone }: { role: string; row: Row; onDone: () => void }) {
  const [amount, setAmount] = useState<unknown>('');
  const [dependent, setDependent] = useState<unknown>('');
  const [attachment, setAttachment] = useState<unknown>('');

  return (
    <Form
      submit="수정"
      note={<span>비워 둔 항목은 바꾸지 않습니다.</span>}
      onSubmit={async () => {
        const body: Row = {};
        if (amount !== '') body.deductionAmount = amount;
        if (dependent !== '') body.dependentInfoEnc = dependent;
        if (attachment !== '') body.attachmentId = attachment;
        if (Object.keys(body).length === 0) {
          throw new Error('수정할 값을 입력하세요.');
        }
        await call('PUT', '/year-end-data/' + String(row.yearEndDataId), role, body);
        onDone();
      }}
    >
      <Field label="공제 금액">
        <NumberInput value={amount} onChange={setAmount} />
      </Field>
      <Field label="부양가족 정보(암호화)" wide>
        <TextInput value={dependent} onChange={setDependent} multiline />
      </Field>
      <Field label="증빙 첨부파일">
        <LookupSelect table="attachment" role={role} value={attachment} onChange={setAttachment} />
      </Field>
    </Form>
  );
}

function CreateForm({ role, onDone }: { role: string; onDone: () => void }) {
  const [employeeId, setEmployeeId] = useState<unknown>('');
  const [itemId, setItemId] = useState<unknown>('');
  const [year, setYear] = useState<unknown>('');
  const [amount, setAmount] = useState<unknown>('');
  const [dependent, setDependent] = useState<unknown>('');
  const [attachment, setAttachment] = useState<unknown>('');

  return (
    <Form
      submit="저장"
      onSubmit={async () => {
        if (employeeId === '' || itemId === '' || year === '') {
          throw new Error('임직원, 연말정산 항목, 귀속 연도는 필수입니다.');
        }
        const body: Row = { employeeId, yearEndItemId: itemId, settlementYear: year };
        if (amount !== '') body.deductionAmount = amount;
        if (dependent !== '') body.dependentInfoEnc = dependent;
        if (attachment !== '') body.attachmentId = attachment;
        await call('POST', '/year-end-data', role, body);
        onDone();
      }}
    >
      <Field label="임직원" required>
        <LookupSelect table="employee" role={role} value={employeeId} onChange={setEmployeeId} />
      </Field>
      <Field label="연말정산 항목" required>
        <LookupSelect table="year_end_item" role={role} value={itemId} onChange={setItemId} />
      </Field>
      <Field label="귀속 연도" required>
        <NumberInput value={year} onChange={setYear} />
      </Field>
      <Field label="공제 금액">
        <NumberInput value={amount} onChange={setAmount} />
      </Field>
      <Field label="부양가족 정보(암호화)" wide>
        <TextInput value={dependent} onChange={setDependent} multiline />
      </Field>
      <Field label="증빙 첨부파일">
        <LookupSelect table="attachment" role={role} value={attachment} onChange={setAttachment} />
      </Field>
    </Form>
  );
}
